// HMAC-SHA256 signature verification on raw body, opt-in, with replay-window check.
// Headers required when WEBHOOK_INTEGRITY_CHECK_ENABLED=1:
//   x-audit-signature: <hex hmac-sha256(timestamp + '.' + rawBody)>
//   x-audit-timestamp: <unix-seconds>
// Plus body-size cap.

const secret = $env.AUDIT_SIGNING_SECRET;
const integrityCheckEnabled = $env.WEBHOOK_INTEGRITY_CHECK_ENABLED === '1';

const MAX_BODY_BYTES = parseInt($env.MAX_BODY_BYTES || '1048576', 10);
const item = $input.first();
const rawBody = item.rawBody || (typeof item.body === 'string' ? item.body : JSON.stringify(item.body || {}));
if (Buffer.byteLength(String(rawBody), 'utf8') > MAX_BODY_BYTES) {
  throw new Error('PAYLOAD_TOO_LARGE: body exceeds MAX_BODY_BYTES=' + MAX_BODY_BYTES);
}

if (!secret || !integrityCheckEnabled) {
  // Verification disabled, mark as unsigned and pass through.
  return [{ json: { signed: false, rawBody, headers: item.headers || {} } }];
}

const crypto = require('crypto');
const headers = item.headers || {};
const providedSig = headers['x-audit-signature'] || headers['X-Audit-Signature'];
const tsHeader = headers['x-audit-timestamp'] || headers['X-Audit-Timestamp'];

if (!providedSig || typeof providedSig !== 'string') {
  throw new Error('UNAUTHORIZED: missing x-audit-signature header');
}
if (!tsHeader || typeof tsHeader !== 'string') {
  throw new Error('UNAUTHORIZED: missing x-audit-timestamp header (replay protection)');
}

const tsNum = parseInt(tsHeader, 10);
if (!Number.isFinite(tsNum)) {
  throw new Error('UNAUTHORIZED: invalid x-audit-timestamp value');
}
const nowSec = Math.floor(Date.now() / 1000);
const REPLAY_WINDOW_S = parseInt($env.AUDIT_REPLAY_WINDOW_S || '300', 10);
if (Math.abs(nowSec - tsNum) > REPLAY_WINDOW_S) {
  throw new Error('UNAUTHORIZED: timestamp outside replay window (' + REPLAY_WINDOW_S + 's)');
}

const signedPayload = tsHeader + '.' + rawBody;
const expected = crypto.createHmac('sha256', secret).update(signedPayload, 'utf8').digest('hex');

if (providedSig.length !== expected.length) {
  throw new Error('UNAUTHORIZED: signature length mismatch');
}

const expBuf = Buffer.from(expected, 'utf8');
const provBuf = Buffer.from(providedSig, 'utf8');
if (!crypto.timingSafeEqual(expBuf, provBuf)) {
  throw new Error('UNAUTHORIZED: invalid signature');
}

return [{ json: { signed: true, rawBody, headers, timestamp: tsNum } }];

// Per-IP sliding-window rate limit, opt-in.
// Default 60 req / 5 min / IP. Rate-limit hits are a DoS signal -> Slack alert in error branch.

if ($env.RATE_LIMIT_ENABLED !== '1') {
  return $input.all();
}

const LIMIT = parseInt($env.AUDIT_RATE_LIMIT_PER_IP || '60', 10);
const WINDOW_MS = 5 * 60 * 1000;
const MAX_KEYS = 5000;

const item = $input.first();
const headers = item.json.headers || {};
const rawIp = headers['x-forwarded-for'] || headers['x-real-ip'] || 'unknown';
const key = String(rawIp).split(',')[0].trim();

const data = $getWorkflowStaticData('global');
data.rateBuckets = data.rateBuckets || {};
const buckets = data.rateBuckets;
const now = Date.now();

for (const k of Object.keys(buckets)) {
  buckets[k] = (buckets[k] || []).filter(t => now - t < WINDOW_MS);
  if (buckets[k].length === 0) delete buckets[k];
}
if (Object.keys(buckets).length > MAX_KEYS) {
  const oldest = Object.entries(buckets).sort((a, b) => (a[1][0] || 0) - (b[1][0] || 0)).slice(0, 100);
  for (const [k] of oldest) delete buckets[k];
}

const hits = buckets[key] || [];
if (hits.length >= LIMIT) {
  throw new Error('RATE_LIMIT_EXCEEDED: ' + LIMIT + ' requests per ' + Math.round(WINDOW_MS / 60000) + ' minutes for ' + key);
}
buckets[key] = [...hits, now];

return $input.all();

// 5-minute idempotency window, opt-in.
// Dedup key preference order: x-request-id header -> sha256(rawBody).
// onError: continueErrorOutput on the node so unexpected static-data corruption is
// caught + routed to Error Fallback rather than escaping as an unhandled exception.

const crypto = require('crypto');

if ($env.IDEMPOTENCY_ENABLED !== '1') {
  return $input.all();
}

const WINDOW_MS = 5 * 60 * 1000;
const MAX_KEYS = 5000;

const item = $input.first();
const headers = item.json.headers || {};
const rawBody = item.json.rawBody || '';
const providedReqId = headers['x-request-id'] || headers['X-Request-Id'];

let dedupKey;
if (providedReqId && typeof providedReqId === 'string' && providedReqId.length <= 128) {
  dedupKey = 'reqid:' + providedReqId;
} else {
  dedupKey = 'body:' + crypto.createHash('sha256').update(rawBody, 'utf8').digest('hex').slice(0, 32);
}

const data = $getWorkflowStaticData('global');
data.seenKeys = data.seenKeys || {};
const seen = data.seenKeys;
const now = Date.now();

for (const k of Object.keys(seen)) {
  if (now - seen[k] > WINDOW_MS) delete seen[k];
}
if (Object.keys(seen).length > MAX_KEYS) {
  const oldest = Object.entries(seen).sort((a, b) => a[1] - b[1]).slice(0, 500);
  for (const [k] of oldest) delete seen[k];
}

if (seen[dedupKey]) {
  return [{ json: { ...item.json, skipped: true, reason: 'duplicate', dedupKey } }];
}
seen[dedupKey] = now;

return [{ json: { ...item.json, dedupKey } }];

// Build the audit row payload.
// Hash chain (prev_hash + row_hash) is computed atomically in the Postgres Insert SQL
// via WITH last AS (SELECT ... FOR UPDATE) + digest() from pgcrypto. We only emit the
// payload + payload_hash + metadata fields here.

const crypto = require('crypto');

const items = $input.all();
const out = [];
for (const item of items) {
  const j = item.json || {};
  if (j.skipped) {
    out.push(item);
    continue;
  }
  const rawBody = j.rawBody || '';
  const headers = j.headers || {};
  const signed = !!j.signed;
  const sourceIp = String(headers['x-forwarded-for'] || headers['x-real-ip'] || '').split(',')[0].trim() || null;
  const sourceUserAgent = headers['user-agent'] || headers['User-Agent'] || null;
  const eventType = headers['x-audit-event-type'] || headers['X-Audit-Event-Type'] || 'unknown';
  const eventSource = headers['x-audit-source'] || headers['X-Audit-Source'] || 'unknown';
  const payloadHash = crypto.createHash('sha256').update(rawBody, 'utf8').digest('hex');

  out.push({ json: {
    receivedAt: new Date().toISOString(),
    eventType,
    eventSource,
    sourceIp,
    sourceUserAgent: sourceUserAgent ? String(sourceUserAgent).slice(0, 500) : null,
    signed,
    payload: rawBody,
    payloadHash,
    dedupKey: j.dedupKey || null,
  }});
}
return out;

// Drop the items that were already deduped before we hit the database.

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (!j.skipped) out.push(item);
}
if (out.length === 0) {
  return [{ json: { skipped: true, reason: 'all-items-deduped' } }];
}
return out;

// Fallback for any failure along the path:
// - HMAC failure (UNAUTHORIZED in Verify) -> security event, alert Slack
// - Rate limit breach (RATE_LIMIT_EXCEEDED in Rate Limit) -> capacity event, alert Slack
// - Idempotency unexpected error -> capacity event, alert Slack
// - DB failure (Postgres Insert) -> the audit chain is broken until DB recovers,
//   alert Slack as security event since auditability is compromised.

const input = $input.first();
const raw = input.json || {};
const errorRaw = raw.error || raw;
const errorMessage = errorRaw && errorRaw.message ? String(errorRaw.message) : 'unknown error';

let category = 'unknown';
let severity = 'warning';
if (errorMessage.startsWith('UNAUTHORIZED')) {
  category = 'auth';
  severity = 'critical';
} else if (errorMessage.startsWith('RATE_LIMIT_EXCEEDED')) {
  category = 'capacity';
  severity = 'warning';
} else if (errorMessage.startsWith('PAYLOAD_TOO_LARGE')) {
  category = 'capacity';
  severity = 'warning';
} else {
  // Likely a DB error if we got past Verify + Rate Limit + Idempotency.
  category = 'database';
  severity = 'critical';
}

// HTTP status to return to the client.
let statusCode = 500;
if (category === 'auth') statusCode = 401;
else if (category === 'capacity') statusCode = 429;
else if (errorMessage.startsWith('PAYLOAD_TOO_LARGE')) statusCode = 413;

return [{ json: {
  ok: false,
  error: errorMessage,
  category,
  severity,
  statusCode,
  at: new Date().toISOString(),
}}];
